  "avaliacoes": [
    {
      "id": "E8bdfd69764b991ab",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Para evitar recorrência em offloading, o alerta recomenda avaliar o cenário de rompimento do mangote no HAZOP e prever salvaguarda de baixa pressão com bloqueio automático.",
          "trechos": [
            "E8bdfd69764b991ab:1386:2082"
          ],
          "condicoes": [
            "aplicado ao contexto do incidente com sistema de offloading/IHTP",
            "como lição aprendida, não como requisito universal"
          ],
          "limites": [
            "o trecho trata de mangote/offloading, não descreve diretamente cabos, guinchos, sheaves ou proof load de pull-in de risers",
            "não informa critérios numéricos, capacidade ou método de teste"
          ]
        },
        {
          "proposicao": "O alerta recomenda verificar a existência de intertravamento e bloqueio automático do sistema e reavaliar salvaguardas de alta e baixa pressão, assegurando seu funcionamento.",
          "trechos": [
            "E8bdfd69764b991ab:1386:2082",
            "E8bdfd69764b991ab:2082:2331"
          ],
          "condicoes": [
            "voltado às unidades e sistemas de offloading citados no alerta"
          ],
          "limites": [
            "não detalha inspeção funcional, proof load ou ensaios de equipamentos de tração",
            "abrangência para operações de pull-in de risers é apenas indireta"
          ]
        },
        {
          "proposicao": "O alerta recomenda verificar nos documentos de fornecedores a existência de recomendações de inspeção, manutenção e teste para equipamentos similares à IHTP.",
          "trechos": [
            "E8bdfd69764b991ab:1386:2082"
          ],
          "condicoes": [
            "no contexto de gestão da documentação e prevenção de falhas similares"
          ],
          "limites": [
            "a recomendação refere-se a equipamentos similares à IHTP",
            "não especifica periodicidade, escopo de inspeção nem critérios de aceitação"
          ]
        }
      ]
    },
    {
      "id": "Ebd32d69dc0588219",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Bend stiffener é descrito como equipamento que suaviza a curvatura do riser flexível próximo à terminação na plataforma por meio de enrijecimento progressivo.",
          "trechos": [
            "Ebd32d69dc0588219:0:699"
          ],
          "condicoes": [
            "aplicável a riser flexível próximo à terminação na plataforma"
          ],
          "limites": [
            "é definição conceitual, sem critérios de seleção, capacidade ou teste"
          ]
        },
        {
          "proposicao": "Pull-in é definido como operação de conexão de alguns equipamentos offshore.",
          "trechos": [
            "Ebd32d69dc0588219:699:1396"
          ],
          "condicoes": [],
          "limites": [
            "definição genérica, sem sequência operacional, equipamentos, cargas ou controles"
          ]
        },
        {
          "proposicao": "Stress-joint é apresentado como análogo ao bend stiffener no aumento progressivo de rigidez, porém normalmente composto de titânio e empregado em dutos rígidos.",
          "trechos": [
            "Ebd32d69dc0588219:1396:2096"
          ],
          "condicoes": [
            "uso em dutos rígidos, conforme o glossário"
          ],
          "limites": [
            "não cobre instalação, inspeção, proof load ou compatibilidade com sistemas específicos de pull-in"
          ]
        }
      ]
    },
    {
      "id": "E45f75c28184a0001",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O incidente relatado ocorreu por rompimento de parafusos fusíveis do QRF, componente do sistema IHTP entre carretel e mangote de offloading, gerando vazamento de óleo para o mar.",
          "trechos": [
            "E45f75c28184a0001:0:696"
          ],
          "condicoes": [
            "durante transferência de óleo do FPSO para navio aliviador"
          ],
          "limites": [
            "trata de offloading, não de pull-in de risers",
            "é descrição de ocorrência específica, não regra geral sobre falhas"
          ]
        },
        {
          "proposicao": "Entre as causas identificadas constam falhas de gestão de mudança e ausência de atualização do HAZOP após alteração que removeu salvaguarda de bloqueio por baixa pressão.",
          "trechos": [
            "E45f75c28184a0001:696:1393",
            "E45f75c28184a0001:1393:2088"
          ],
          "condicoes": [
            "após alteração do sistema e urgência na retomada das operações"
          ],
          "limites": [
            "não há detalhamento de metodologia de análise de carga, capacidade ou testes de tração"
          ]
        },
        {
          "proposicao": "Também foram apontadas ausência de requisito de acabamento superficial dos parafusos fusíveis e de intertravamento para a posição correta do carretel para offloading.",
          "trechos": [
            "E45f75c28184a0001:1393:2088",
            "E45f75c28184a0001:2088:2283"
          ],
          "condicoes": [
            "no contexto do projeto do sistema investigado"
          ],
          "limites": [
            "não informa critérios técnicos de acabamento, intertravamento ou verificação",
            "aplicação direta ao recorte de cabos/guinchos/sheaves é limitada"
          ]
        }
      ]
    },
    {
      "id": "E8ec0cfc77f7c3b61",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O projeto básico de FPSO citado prevê uso de sistema de pull-in móvel para permitir instalação e substituição de risers com maior segurança e flexibilidade operacional.",
          "trechos": [
            "E8ec0cfc77f7c3b61:696:1392"
          ],
          "condicoes": [
            "no projeto mencionado para Cernambi Norte"
          ],
          "limites": [
            "não descreve a arquitetura do sistema móvel, seus cabos, guinchos, guias ou capacidade",
            "a alegação de maior segurança e flexibilidade é contextual ao projeto citado"
          ]
        }
      ]
    },
    {
      "id": "E90c3f4af78960edd",
      "pertinente": true,
      "tipo": "opiniao",
      "achados": [
        {
          "proposicao": "Segundo a fonte, o conceito BSR buscou viabilização de procedimentos de instalação no mercado nacional sem grandes aportes de recursos e sem grandes dificuldades, apesar de ser tecnologia pioneira.",
          "trechos": [
            "E90c3f4af78960edd:0:697"
          ],
          "condicoes": [
            "relato atribuído ao desenvolvimento do conceito BSR"
          ],
          "limites": [
            "caráter de depoimento/opinião",
            "não apresenta comprovação metodológica, critérios de capacidade nem testes"
          ]
        },
        {
          "proposicao": "A fonte atribui ao sistema BSR a vantagem de desacoplar os movimentos dos risers da plataforma, permitindo escolha da unidade de produção.",
          "trechos": [
            "E90c3f4af78960edd:697:1397"
          ],
          "condicoes": [
            "no contexto do conceito BSR descrito"
          ],
          "limites": [
            "não detalha mecanismo completo, condições de validade ou comparações quantitativas"
          ]
        },
        {
          "proposicao": "A mesma fonte atribui ao sistema BSR a redução das cargas de topo dos risers e da complexidade, tempo e risco nas operações de pull-in e pull-out.",
          "trechos": [
            "E90c3f4af78960edd:697:1397"
          ],
          "condicoes": [
            "vantagens declaradas para o sistema BSR"
          ],
          "limites": [
            "não informa magnitude da redução, critérios de projeto, inspeção ou proof load",
            "trata-se de afirmação da fonte, não de norma"
          ]
        }
      ]
    },
    {
